style.css:
@-moz-document domain("youtube.com"), domain("www.youtube.com") {
/* Fondo azul apagado general */
  html, body, ytd-app, #page-manager, #content, #primary, #columns {
    background: #0d1b2a !important; /* azul apagado */
    margin: 0 !important;
    padding: 0 !important;
    width: 100% !important;
    max-width: 100% !important;
    min-width: 0 !important;
    overflow-x: hidden !important;
  }

  /* Menú lateral (barra izquierda) */
  #guide-content.ytd-app, 
  #guide-inner-content, 
  #guide, 
  #sections {
    background-color: #0b1623 !important; /* azul más oscuro para diferenciar */
    border-right: 1px solid #14273d !important; /* línea divisoria */
  }

  /* Opciones del menú */
  ytd-guide-entry-renderer, 
  ytd-mini-guide-entry-renderer {
    background-color: transparent !important;
    color: #e6eef6 !important;
    padding: 6px 12px !important;
    border-radius: 6px !important;
  }

  /* Hover en menú */
  ytd-guide-entry-renderer:hover, 
  ytd-mini-guide-entry-renderer:hover {
    background-color: #14273d !important;
  }

  /* Textos generales */
  yt-formatted-string, 
  #text, 
  .title, 
  .yt-simple-endpoint {
    color: #e6eef6 !important;
  }
}
